import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import java.net.SocketAddress;
import junit.framework.TestCase;
import org.junit.Test;
import org.mockito.Mockito;

public class WatchProtocolDecoderTests extends TestCase {

    @Test
    public void getHasIndexDefaultCaseTest() {
        WatchProtocolDecoder protocolDecoder = new WatchProtocolDecoder(new Protocol("WatchProtocol"));
        assertEquals(false, protocolDecoder.getHasIndex());
    }

    @Test
    public void getManufacturerCaseTest() {
        WatchProtocolDecoder protocolDecoder = new WatchProtocolDecoder(new Protocol("WatchProtocol"));
        assertEquals("Watch Protocol", protocolDecoder.getManufacturer());
    }

    @Test
    public void decodeNullCaseTest() throws Exception {
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress socketAddress = Mockito.mock(SocketAddress.class);
        WatchProtocolDecoder protocolDecoder = new WatchProtocolDecoder(new Protocol("WatchProtocol"));

        try {
            protocolDecoder.decode(channel, socketAddress, null);
            fail("Expected Exception not thrown");
        } catch (Exception ex) {
            assertEquals("Input is null", ex.getMessage());
        }
    }

    @Test
    public void decodeWrongObjectTypeCaseTest() throws Exception {
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress socketAddress = Mockito.mock(SocketAddress.class);
        WatchProtocolDecoder protocolDecoder = new WatchProtocolDecoder(new Protocol("WatchProtocol"));

        try {
            protocolDecoder.decode(channel, socketAddress, "WrongType");
            fail("Expected Exception not thrown");
        } catch (Exception ex) {
            assertEquals("Input is not of correct type", ex.getMessage());
        }
    }

    @Test
    public void decodeCorrectObjectTypeCaseTest() throws Exception {
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress socketAddress = Mockito.mock(SocketAddress.class);
        WatchProtocolDecoder protocolDecoder = new WatchProtocolDecoder(new Protocol("WatchProtocol"));

        byte[] byteArray = {1, 2, 3};
        Object obj = Unpooled.copiedBuffer(byteArray);

        assertEquals(obj, protocolDecoder.decode(channel, socketAddress, obj));
    }
}
